#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

#include <polybench.h>

#include "2mm.h"

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

static
void init_array(int ni, int nj, int nk, int nl,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(C,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nk; j++)
      A[i][j] = (DATA_TYPE) ((i*j+1) % ni) / ni;
  for (i = 0; i < nk; i++)
    for (j = 0; j < nj; j++)
      B[i][j] = (DATA_TYPE) (i*(j+1) % nj) / nj;
  for (i = 0; i < nj; i++)
    for (j = 0; j < nl; j++)
      C[i][j] = (DATA_TYPE) ((i*(j+3)+1) % nl) / nl;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++)
      D[i][j] = (DATA_TYPE) (i*(j+2) % nk) / nk;
}

static
void print_array(int ni, int nl,
		 DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("D");
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, D[i][j]);
    }
  POLYBENCH_DUMP_END("D");
  POLYBENCH_DUMP_FINISH;
}

static
void kernel_2mm(int ni, int nj, int nk, int nl,
		DATA_TYPE alpha,
		DATA_TYPE beta,
		DATA_TYPE POLYBENCH_2D(tmp,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(C,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  int i, j, k;

#pragma scop

#if defined(__riscv_vector)
  for (i = 0; i < _PB_NI; i++) {
    for (j = 0; j < _PB_NJ; j++) {
      size_t k2 = 0;
      vfloat32m1_t vsum = __riscv_vfmv_v_f_f32m1((DATA_TYPE)0.0, 1);
      for (; k2 < (size_t)_PB_NK; ) {
        size_t vl = __riscv_vsetvl_e32m1((size_t)_PB_NK - k2);
        vfloat32m1_t va = __riscv_vle32_v_f32m1(&A[i][k2], vl);
        vfloat32m1_t vb = __riscv_vle32_v_f32m1(&B[k2][j], vl);
        vfloat32m1_t vm = __riscv_vfmul_vf_f32m1(va, alpha, vl);
        vm = __riscv_vfmul_vv_f32m1(vm, vb, vl);
        vsum = __riscv_vfadd_vv_f32m1(vsum, vm, vl);
        k2 += vl;
      }
      tmp[i][j] = __riscv_vfredosum_vs_f32m1_f32m1(vsum, __riscv_vfmv_v_f_f32m1((DATA_TYPE)0.0, 1), 1)[0];
    }
  }
#else
  for (i = 0; i < _PB_NI; i++)
    for (j = 0; j < _PB_NJ; j++)
      {
	tmp[i][j] = SCALAR_VAL(0.0);
	for (k = 0; k < _PB_NK; ++k)
	  tmp[i][j] += alpha * A[i][k] * B[k][j];
      }
#endif

#if defined(__riscv_vector)
  for (i = 0; i < _PB_NI; i++) {
    for (j = 0; j < _PB_NL; j++) {
      DATA_TYPE acc = D[i][j] * beta;
      size_t k2 = 0;
      for (; k2 < (size_t)_PB_NJ; ) {
        size_t vl = __riscv_vsetvl_e32m1((size_t)_PB_NJ - k2);
        vfloat32m1_t vt = __riscv_vle32_v_f32m1(&tmp[i][k2], vl);
        vfloat32m1_t vc = __riscv_vle32_v_f32m1(&C[k2][j], vl);
        vfloat32m1_t vp = __riscv_vfmul_vv_f32m1(vt, vc, vl);
        acc += __riscv_vfredosum_vs_f32m1_f32m1(vp, __riscv_vfmv_v_f_f32m1((DATA_TYPE)0.0, 1), 1)[0];
        k2 += vl;
      }
      D[i][j] = acc;
    }
  }
#else
  for (i = 0; i < _PB_NI; i++)
    for (j = 0; j < _PB_NL; j++)
      {
	D[i][j] *= beta;
	for (k = 0; k < _PB_NJ; ++k)
	  D[i][j] += tmp[i][k] * C[k][j];
      }
#endif

#pragma endscop

}

