static
void kernel_3mm(int ni, int nj, int nk, int nl, int nm,
		DATA_TYPE POLYBENCH_2D(E,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(F,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(C,NJ,NM,nj,nm),
		DATA_TYPE POLYBENCH_2D(D,NM,NL,nm,nl),
		DATA_TYPE POLYBENCH_2D(G,NI,NL,ni,nl))
{
  int i, j, k;

#pragma scop

#if defined(__riscv_vector) && defined(DATA_TYPE_IS_FLOAT)
  for (i = 0; i < _PB_NI; i++) {
    for (j = 0; j < _PB_NJ; j++) {
      DATA_TYPE sum = SCALAR_VAL(0.0);
      for (k = 0; k < _PB_NK; ) {
        size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_NK - k));
        vfloat32m1_t va = __riscv_vle32_v_f32m1((const float *)&A[i][k], vl);
        vfloat32m1_t vb = __riscv_vle32_v_f32m1((const float *)&B[k][j], vl);
        vfloat32m1_t vm = __riscv_vfmul_vv_f32m1(va, vb, vl);
        sum += __riscv_vfmv_f_s_f32m1_f32(
            __riscv_vfredosum_vs_f32m1_f32m1(
                __riscv_vfmv_s_f_f32m1(0.0f, vl), vm,
                __riscv_vfmv_s_f_f32m1(0.0f, vl), vl));
        k += (int)vl;
      }
      E[i][j] = sum;
    }
  }

  for (i = 0; i < _PB_NJ; i++) {
    for (j = 0; j < _PB_NL; j++) {
      DATA_TYPE sum = SCALAR_VAL(0.0);
      for (k = 0; k < _PB_NM; ) {
        size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_NM - k));
        vfloat32m1_t vc = __riscv_vle32_v_f32m1((const float *)&C[i][k], vl);
        vfloat32m1_t vd = __riscv_vle32_v_f32m1((const float *)&D[k][j], vl);
        vfloat32m1_t vm = __riscv_vfmul_vv_f32m1(vc, vd, vl);
        sum += __riscv_vfmv_f_s_f32m1_f32(
            __riscv_vfredosum_vs_f32m1_f32m1(
                __riscv_vfmv_s_f_f32m1(0.0f, vl), vm,
                __riscv_vfmv_s_f_f32m1(0.0f, vl), vl));
        k += (int)vl;
      }
      F[i][j] = sum;
    }
  }

  for (i = 0; i < _PB_NI; i++) {
    for (j = 0; j < _PB_NL; j++) {
      DATA_TYPE sum = SCALAR_VAL(0.0);
      for (k = 0; k < _PB_NJ; ) {
        size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_NJ - k));
        vfloat32m1_t ve = __riscv_vle32_v_f32m1((const float *)&E[i][k], vl);
        vfloat32m1_t vf = __riscv_vle32_v_f32m1((const float *)&F[k][j], vl);
        vfloat32m1_t vm = __riscv_vfmul_vv_f32m1(ve, vf, vl);
        sum += __riscv_vfmv_f_s_f32m1_f32(
            __riscv_vfredosum_vs_f32m1_f32m1(
                __riscv_vfmv_s_f_f32m1(0.0f, vl), vm,
                __riscv_vfmv_s_f_f32m1(0.0f, vl), vl));
        k += (int)vl;
      }
      G[i][j] = sum;
    }
  }
#else
  for (i = 0; i < _PB_NI; i++)
    for (j = 0; j < _PB_NJ; j++)
      {
	E[i][j] = SCALAR_VAL(0.0);
	for (k = 0; k < _PB_NK; ++k)
	  E[i][j] += A[i][k] * B[k][j];
      }

  for (i = 0; i < _PB_NJ; i++)
    for (j = 0; j < _PB_NL; j++)
      {
	F[i][j] = SCALAR_VAL(0.0);
	for (k = 0; k < _PB_NM; ++k)
	  F[i][j] += C[i][k] * D[k][j];
      }

  for (i = 0; i < _PB_NI; i++)
    for (j = 0; j < _PB_NL; j++)
      {
	G[i][j] = SCALAR_VAL(0.0);
	for (k = 0; k < _PB_NJ; ++k)
	  G[i][j] += E[i][k] * F[k][j];
      }
#endif

#pragma endscop

}

