static
void init_array(int m, int n,
		DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		DATA_TYPE POLYBENCH_1D(x,N,n))
{
  int i, j;
  DATA_TYPE fn;
  fn = (DATA_TYPE)n;

  for (i = 0; i < n; i++)
    x[i] = 1 + (i / fn);
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++)
      A[i][j] = (DATA_TYPE)((i + j) % n) / (5 * m);
}

static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("y");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
    fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, y[i]);
  }
  POLYBENCH_DUMP_END("y");
  POLYBENCH_DUMP_FINISH;
}

static
void kernel_atax(int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n),
		 DATA_TYPE POLYBENCH_1D(tmp,M,m))
{
  int i, j;

#pragma scop
  for (j = 0; j < _PB_N; ) {
    size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_N - j));
    vfloat64m1_t vy = __riscv_vfmv_v_f_f64m1(0.0, vl);
    __riscv_vse64_v_f64m1((double *)&y[j], vy, vl);
    j += (int)vl;
  }

  for (i = 0; i < _PB_M; i++) {
    DATA_TYPE acc = SCALAR_VAL(0.0);
    DATA_TYPE *Ai = (DATA_TYPE *)&A[i][0];

    for (j = 0; j < _PB_N; ) {
      size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_N - j));
      vfloat64m1_t va = __riscv_vle64_v_f64m1((const double *)&Ai[j], vl);
      vfloat64m1_t vx = __riscv_vle64_v_f64m1((const double *)&x[j], vl);
      vfloat64m1_t vprod = __riscv_vfmul_vv_f64m1(va, vx, vl);
      vfloat64m1_t vzero = __riscv_vfmv_v_f_f64m1(0.0, 1);
      vfloat64m1_t vsum = __riscv_vfredusum_vs_f64m1_f64m1(vprod, vzero, vl);
      acc += (DATA_TYPE)__riscv_vfmv_f_s_f64m1_f64(vsum);
      j += (int)vl;
    }

    tmp[i] = acc;

    for (j = 0; j < _PB_N; ) {
      size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_N - j));
      vfloat64m1_t va = __riscv_vle64_v_f64m1((const double *)&Ai[j], vl);
      vfloat64m1_t vy = __riscv_vle64_v_f64m1((const double *)&y[j], vl);
      vy = __riscv_vfmacc_vf_f64m1(vy, (double)acc, va, vl);
      __riscv_vse64_v_f64m1((double *)&y[j], vy, vl);
      j += (int)vl;
    }
  }
#pragma endscop
}

#include <stdio.h>
