static
void init_array (int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		 DATA_TYPE POLYBENCH_1D(r,N,n),
		 DATA_TYPE POLYBENCH_1D(p,M,m))
{
  int i, j;

  for (i = 0; i < m; i++)
    p[i] = (DATA_TYPE)(i % m) / m;
  for (i = 0; i < n; i++) {
    r[i] = (DATA_TYPE)(i % n) / n;
    for (j = 0; j < m; j++)
      A[i][j] = (DATA_TYPE) (i*(j+1) % n)/n;
  }
}

static
void print_array(int m, int n,
		 DATA_TYPE POLYBENCH_1D(s,M,m),
		 DATA_TYPE POLYBENCH_1D(q,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("s");
  for (i = 0; i < m; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, s[i]);
  }
  POLYBENCH_DUMP_END("s");
  POLYBENCH_DUMP_BEGIN("q");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, q[i]);
  }
  POLYBENCH_DUMP_END("q");
  POLYBENCH_DUMP_FINISH;
}

static
void kernel_bicg(int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		 DATA_TYPE POLYBENCH_1D(s,M,m),
		 DATA_TYPE POLYBENCH_1D(q,N,n),
		 DATA_TYPE POLYBENCH_1D(p,M,m),
		 DATA_TYPE POLYBENCH_1D(r,N,n))
{
  int i;

#pragma scop
  {
    int j0 = 0;
    while (j0 < _PB_M) {
      size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_M - j0));
      vfloat64m1_t vz = __riscv_vfmv_v_f_f64m1(0.0, vl);
      __riscv_vse64_v_f64m1(&s[j0], vz, vl);
      j0 += (int)vl;
    }

    for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE qi = SCALAR_VAL(0.0);
      DATA_TYPE ri = r[i];
      DATA_TYPE *Ai = &A[i][0];

      int j = 0;
      while (j < _PB_M) {
        size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_M - j));

        vfloat64m1_t va = __riscv_vle64_v_f64m1(&Ai[j], vl);
        vfloat64m1_t vs = __riscv_vle64_v_f64m1(&s[j], vl);
        vfloat64m1_t vp = __riscv_vle64_v_f64m1(&p[j], vl);

        vs = __riscv_vfmacc_vf_f64m1(vs, ri, va, vl);
        __riscv_vse64_v_f64m1(&s[j], vs, vl);

        vfloat64m1_t vprod = __riscv_vfmul_vv_f64m1(va, vp, vl);
        vfloat64m1_t vzero = __riscv_vfmv_v_f_f64m1(0.0, 1);
        vfloat64m1_t vred = __riscv_vfredusum_vs_f64m1_f64m1(vprod, vzero, vl);
        qi += __riscv_vfmv_f_s_f64m1_f64(vred);

        j += (int)vl;
      }

      q[i] = qi;
    }
  }
#pragma endscop
}

#include <stdio.h>
#include <unistd.h>
