static
void init_array(int n,
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    {
      for (j = 0; j <= i; j++)
	A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
      for (j = i+1; j < n; j++) {
	A[i][j] = 0;
      }
      A[i][i] = 1;
    }

  int r,s,t;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);
  for (r = 0; r < n; ++r)
    for (s = 0; s < n; ++s)
      (POLYBENCH_ARRAY(B))[r][s] = 0;
  for (t = 0; t < n; ++t)
    for (r = 0; r < n; ++r)
      for (s = 0; s < n; ++s)
	(POLYBENCH_ARRAY(B))[r][s] += A[r][t] * A[s][t];
  for (r = 0; r < n; ++r)
    for (s = 0; s < n; ++s)
      A[r][s] = (POLYBENCH_ARRAY(B))[r][s];
  POLYBENCH_FREE_ARRAY(B);
}

static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j <= i; j++) {
      if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}

static inline DATA_TYPE rvv_dot_product(const DATA_TYPE *a, const DATA_TYPE *b, int len)
{
  DATA_TYPE sum = (DATA_TYPE)0;
  int p = 0;

  if (sizeof(DATA_TYPE) == sizeof(double)) {
    while (p < len) {
      size_t vl = __riscv_vsetvl_e64m1((size_t)(len - p));
      vfloat64m1_t va = __riscv_vle64_v_f64m1((const double *)&a[p], vl);
      vfloat64m1_t vb = __riscv_vle64_v_f64m1((const double *)&b[p], vl);
      vfloat64m1_t vmul = __riscv_vfmul_vv_f64m1(va, vb, vl);
      vfloat64m1_t vzero = __riscv_vfmv_v_f_f64m1(0.0, vl);
      vfloat64m1_t vred = __riscv_vfredusum_vs_f64m1_f64m1(vmul, vzero, vl);
      sum += (DATA_TYPE)__riscv_vfmv_f_s_f64m1_f64(vred);
      p += (int)vl;
    }
  } else {
    while (p < len) {
      size_t vl = __riscv_vsetvl_e32m1((size_t)(len - p));
      vfloat32m1_t va = __riscv_vle32_v_f32m1((const float *)&a[p], vl);
      vfloat32m1_t vb = __riscv_vle32_v_f32m1((const float *)&b[p], vl);
      vfloat32m1_t vmul = __riscv_vfmul_vv_f32m1(va, vb, vl);
      vfloat32m1_t vzero = __riscv_vfmv_v_f_f32m1(0.0f, vl);
      vfloat32m1_t vred = __riscv_vfredusum_vs_f32m1_f32m1(vmul, vzero, vl);
      sum += (DATA_TYPE)__riscv_vfmv_f_s_f32m1_f32(vred);
      p += (int)vl;
    }
  }

  return sum;
}

static
void kernel_cholesky(int n,
		     DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *Ai = &A[i][0];

    for (j = 0; j < i; j++) {
      DATA_TYPE *Aj = &A[j][0];
      DATA_TYPE sum = rvv_dot_product(Ai, Aj, j);
      Ai[j] -= sum;
      Ai[j] /= Aj[j];
    }

    {
      DATA_TYPE sum = rvv_dot_product(Ai, Ai, i);
      Ai[i] -= sum;
      Ai[i] = SQRT_FUN(Ai[i]);
    }
  }
#pragma endscop
}

