static
void kernel_correlation(int m, int n,
			DATA_TYPE float_n,
			DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
			DATA_TYPE POLYBENCH_2D(corr,M,M,m,m),
			DATA_TYPE POLYBENCH_1D(mean,M,m),
			DATA_TYPE POLYBENCH_1D(stddev,M,m))
{
  int i, j, k;
  DATA_TYPE eps = SCALAR_VAL(0.1);
  DATA_TYPE sqfn = SQRT_FUN(float_n);

#pragma scop
  for (j = 0; j < _PB_M; j++)
    {
      mean[j] = SCALAR_VAL(0.0);
      for (i = 0; i < _PB_N; i++)
	mean[j] += data[i][j];
      mean[j] /= float_n;
    }

  for (j = 0; j < _PB_M; j++)
    {
      stddev[j] = SCALAR_VAL(0.0);
      for (i = 0; i < _PB_N; i++)
        {
          DATA_TYPE d = data[i][j] - mean[j];
          stddev[j] += d * d;
        }
      stddev[j] /= float_n;
      stddev[j] = SQRT_FUN(stddev[j]);
      stddev[j] = stddev[j] <= eps ? SCALAR_VAL(1.0) : stddev[j];
    }

#if defined(__riscv_vector)

  for (i = 0; i < _PB_N; i++)
    {
      int jj = 0;
      while (jj < _PB_M)
        {
          size_t vl = __riscv_vsetvl_e64m4((size_t)(_PB_M - jj));
          vfloat64m4_t vdata = __riscv_vle64_v_f64m4((const double *)&data[i][jj], vl);
          vfloat64m4_t vmean = __riscv_vle64_v_f64m4((const double *)&mean[jj], vl);
          vfloat64m4_t vstd  = __riscv_vle64_v_f64m4((const double *)&stddev[jj], vl);
          vfloat64m4_t vnum  = __riscv_vfsub_vv_f64m4(vdata, vmean, vl);
          vfloat64m4_t vden  = __riscv_vfmul_vf_f64m4(vstd, sqfn, vl);
          vfloat64m4_t vres  = __riscv_vfdiv_vv_f64m4(vnum, vden, vl);
          __riscv_vse64_v_f64m4((double *)&data[i][jj], vres, vl);
          jj += (int)vl;
        }
    }

  for (i = 0; i < _PB_M-1; i++)
    {
      corr[i][i] = SCALAR_VAL(1.0);
      for (j = i+1; j < _PB_M; j++)
        {
          DATA_TYPE sum = SCALAR_VAL(0.0);
          for (k = 0; k < _PB_N; )
            {
              size_t vl = __riscv_vsetvl_e64m4((size_t)(_PB_N - k));
              vfloat64m4_t vacc = __riscv_vfmv_v_f_f64m4(SCALAR_VAL(0.0), vl);
              vfloat64m1_t vzero = __riscv_vfmv_s_f_f64m1(SCALAR_VAL(0.0), 1);
              size_t t = 0;
              while (t < vl)
                {
                  size_t vlseg = __riscv_vsetvl_e64m4(vl - t);
                  const double *pi = (const double *)&data[k + (int)t][i];
                  const double *pj = (const double *)&data[k + (int)t][j];
                  ptrdiff_t stride = (ptrdiff_t)(M * sizeof(DATA_TYPE));
                  vfloat64m4_t vi = __riscv_vlse64_v_f64m4(pi, stride, vlseg);
                  vfloat64m4_t vj = __riscv_vlse64_v_f64m4(pj, stride, vlseg);
                  vacc = __riscv_vfmacc_vv_f64m4(vacc, vi, vj, vlseg);
                  t += vlseg;
                }
              vfloat64m1_t vred = __riscv_vfredosum_vs_f64m4_f64m1(vacc, vzero, vl);
              sum += __riscv_vfmv_f_s_f64m1_f64(vred);
              k += (int)vl;
            }
          corr[i][j] = sum;
          corr[j][i] = corr[i][j];
        }
    }

#else

  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_M; j++)
      {
        data[i][j] -= mean[j];
        data[i][j] /= sqfn * stddev[j];
      }

  for (i = 0; i < _PB_M-1; i++)
    {
      corr[i][i] = SCALAR_VAL(1.0);
      for (j = i+1; j < _PB_M; j++)
        {
          corr[i][j] = SCALAR_VAL(0.0);
          for (k = 0; k < _PB_N; k++)
            corr[i][j] += (data[k][i] * data[k][j]);
          corr[j][i] = corr[i][j];
        }
    }

#endif

  corr[_PB_M-1][_PB_M-1] = SCALAR_VAL(1.0);
#pragma endscop

}

