static
void kernel_covariance(int m, int n,
		       DATA_TYPE float_n,
		       DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
		       DATA_TYPE POLYBENCH_2D(cov,M,M,m,m),
		       DATA_TYPE POLYBENCH_1D(mean,M,m))
{
  int i, j, k;

#pragma scop
#if defined(DATA_TYPE_IS_DOUBLE)

  for (j = 0; j < _PB_M; ++j)
    {
      DATA_TYPE sum = SCALAR_VAL(0.0);
      int ii = 0;
      while (ii < _PB_N)
        {
          size_t vl = __riscv_vsetvl_e64m4(_PB_N - ii);
          vfloat64m4_t vcol = __riscv_vlse64_v_f64m4(&data[ii][j], (ptrdiff_t)(m * sizeof(DATA_TYPE)), vl);
          vfloat64m1_t vred = __riscv_vfmv_v_f_f64m1(sum, 1);
          vred = __riscv_vfredusum_vs_f64m4_f64m1(vcol, vred, vl);
          sum = __riscv_vfmv_f_s_f64m1_f64(vred);
          ii += (int)vl;
        }
      mean[j] = sum / float_n;
    }

  for (i = 0; i < _PB_N; ++i)
    {
      int jj = 0;
      while (jj < _PB_M)
        {
          size_t vl = __riscv_vsetvl_e64m4(_PB_M - jj);
          vfloat64m4_t vdata = __riscv_vle64_v_f64m4(&data[i][jj], vl);
          vfloat64m4_t vmean = __riscv_vle64_v_f64m4(&mean[jj], vl);
          vdata = __riscv_vfsub_vv_f64m4(vdata, vmean, vl);
          __riscv_vse64_v_f64m4(&data[i][jj], vdata, vl);
          jj += (int)vl;
        }
    }

  {
    const DATA_TYPE denom = float_n - SCALAR_VAL(1.0);
    const DATA_TYPE rdenom = SCALAR_VAL(1.0) / denom;

    for (i = 0; i < _PB_M; ++i)
      {
        DATA_TYPE sum_ii = SCALAR_VAL(0.0);
        for (k = 0; k < _PB_N; ++k)
          {
            DATA_TYPE dik = data[k][i];
            sum_ii += dik * dik;
          }
        cov[i][i] = sum_ii * rdenom;

        for (j = i + 1; j < _PB_M; )
          {
            size_t vl = __riscv_vsetvl_e64m4(_PB_M - j);
            vfloat64m4_t vacc = __riscv_vfmv_v_f_f64m4(0.0, vl);

            for (k = 0; k < _PB_N; ++k)
              {
                DATA_TYPE dik = data[k][i];
                vfloat64m4_t vj = __riscv_vle64_v_f64m4(&data[k][j], vl);
                vacc = __riscv_vfmacc_vf_f64m4(vacc, dik, vj, vl);
              }

            vacc = __riscv_vfmul_vf_f64m4(vacc, rdenom, vl);
            __riscv_vse64_v_f64m4(&cov[i][j], vacc, vl);

            {
              size_t t;
              DATA_TYPE buf[1024];
              __riscv_vse64_v_f64m4(buf, vacc, vl);
              for (t = 0; t < vl; ++t)
                cov[j + (int)t][i] = buf[t];
            }

            j += (int)vl;
          }
      }
  }

#elif defined(DATA_TYPE_IS_FLOAT)

  for (j = 0; j < _PB_M; ++j)
    {
      DATA_TYPE sum = SCALAR_VAL(0.0);
      int ii = 0;
      while (ii < _PB_N)
        {
          size_t vl = __riscv_vsetvl_e32m8(_PB_N - ii);
          vfloat32m8_t vcol = __riscv_vlse32_v_f32m8(&data[ii][j], (ptrdiff_t)(m * sizeof(DATA_TYPE)), vl);
          vfloat32m1_t vred = __riscv_vfmv_v_f_f32m1(sum, 1);
          vred = __riscv_vfredusum_vs_f32m8_f32m1(vcol, vred, vl);
          sum = __riscv_vfmv_f_s_f32m1_f32(vred);
          ii += (int)vl;
        }
      mean[j] = sum / float_n;
    }

  for (i = 0; i < _PB_N; ++i)
    {
      int jj = 0;
      while (jj < _PB_M)
        {
          size_t vl = __riscv_vsetvl_e32m8(_PB_M - jj);
          vfloat32m8_t vdata = __riscv_vle32_v_f32m8(&data[i][jj], vl);
          vfloat32m8_t vmean = __riscv_vle32_v_f32m8(&mean[jj], vl);
          vdata = __riscv_vfsub_vv_f32m8(vdata, vmean, vl);
          __riscv_vse32_v_f32m8(&data[i][jj], vdata, vl);
          jj += (int)vl;
        }
    }

  {
    const DATA_TYPE denom = float_n - SCALAR_VAL(1.0);
    const DATA_TYPE rdenom = SCALAR_VAL(1.0) / denom;

    for (i = 0; i < _PB_M; ++i)
      {
        DATA_TYPE sum_ii = SCALAR_VAL(0.0);
        for (k = 0; k < _PB_N; ++k)
          {
            DATA_TYPE dik = data[k][i];
            sum_ii += dik * dik;
          }
        cov[i][i] = sum_ii * rdenom;

        for (j = i + 1; j < _PB_M; )
          {
            size_t vl = __riscv_vsetvl_e32m8(_PB_M - j);
            vfloat32m8_t vacc = __riscv_vfmv_v_f_f32m8(0.0f, vl);

            for (k = 0; k < _PB_N; ++k)
              {
                DATA_TYPE dik = data[k][i];
                vfloat32m8_t vj = __riscv_vle32_v_f32m8(&data[k][j], vl);
                vacc = __riscv_vfmacc_vf_f32m8(vacc, dik, vj, vl);
              }

            vacc = __riscv_vfmul_vf_f32m8(vacc, rdenom, vl);
            __riscv_vse32_v_f32m8(&cov[i][j], vacc, vl);

            {
              size_t t;
              DATA_TYPE buf[2048];
              __riscv_vse32_v_f32m8(buf, vacc, vl);
              for (t = 0; t < vl; ++t)
                cov[j + (int)t][i] = buf[t];
            }

            j += (int)vl;
          }
      }
  }

#else

  for (j = 0; j < _PB_M; j++)
    {
      mean[j] = SCALAR_VAL(0.0);
      for (i = 0; i < _PB_N; i++)
        mean[j] += data[i][j];
      mean[j] /= float_n;
    }

  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_M; j++)
      data[i][j] -= mean[j];

  for (i = 0; i < _PB_M; i++)
    for (j = i; j < _PB_M; j++)
      {
        cov[i][j] = SCALAR_VAL(0.0);
        for (k = 0; k < _PB_N; k++)
	  cov[i][j] += data[k][i] * data[k][j];
        cov[i][j] /= (float_n - SCALAR_VAL(1.0));
        cov[j][i] = cov[i][j];
      }

#endif
#pragma endscop

}

