void kernel_doitgen(int nr, int nq, int np,
		    DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np),
		    DATA_TYPE POLYBENCH_2D(C4,NP,NP,np,np),
		    DATA_TYPE POLYBENCH_1D(sum,NP,np))
{
  int r, q, p, s;

#pragma scop
  for (r = 0; r < _PB_NR; r++) {
    for (q = 0; q < _PB_NQ; q++) {
      DATA_TYPE *a_rq = &A[r][q][0];

      {
        size_t vl;
        int p_idx = 0;
        for (; p_idx < _PB_NP; p_idx += (int)vl) {
          if (sizeof(DATA_TYPE) == sizeof(float)) {
            vl = __riscv_vsetvl_e32m1((size_t)(_PB_NP - p_idx));
            __riscv_vse32_v_f32m1((float *)&sum[p_idx],
                                  __riscv_vfmv_v_f_f32m1(0.0f, vl), vl);
          } else {
            vl = __riscv_vsetvl_e64m1((size_t)(_PB_NP - p_idx));
            __riscv_vse64_v_f64m1((double *)&sum[p_idx],
                                  __riscv_vfmv_v_f_f64m1(0.0, vl), vl);
          }
        }
      }

      for (s = 0; s < _PB_NP; s++) {
        DATA_TYPE a_scalar = a_rq[s];
        DATA_TYPE *c4_row = &C4[s][0];
        size_t vl;
        int p_idx = 0;

        if (sizeof(DATA_TYPE) == sizeof(float)) {
          float a_val = (float)a_scalar;
          for (; p_idx < _PB_NP; p_idx += (int)vl) {
            vl = __riscv_vsetvl_e32m1((size_t)(_PB_NP - p_idx));
            vfloat32m1_t v_sum = __riscv_vle32_v_f32m1((const float *)&sum[p_idx], vl);
            vfloat32m1_t v_c4  = __riscv_vle32_v_f32m1((const float *)&c4_row[p_idx], vl);
            v_sum = __riscv_vfmacc_vf_f32m1(v_sum, a_val, v_c4, vl);
            __riscv_vse32_v_f32m1((float *)&sum[p_idx], v_sum, vl);
          }
        } else {
          double a_val = (double)a_scalar;
          for (; p_idx < _PB_NP; p_idx += (int)vl) {
            vl = __riscv_vsetvl_e64m1((size_t)(_PB_NP - p_idx));
            vfloat64m1_t v_sum = __riscv_vle64_v_f64m1((const double *)&sum[p_idx], vl);
            vfloat64m1_t v_c4  = __riscv_vle64_v_f64m1((const double *)&c4_row[p_idx], vl);
            v_sum = __riscv_vfmacc_vf_f64m1(v_sum, a_val, v_c4, vl);
            __riscv_vse64_v_f64m1((double *)&sum[p_idx], v_sum, vl);
          }
        }
      }

      {
        size_t vl;
        int p_idx = 0;
        if (sizeof(DATA_TYPE) == sizeof(float)) {
          for (; p_idx < _PB_NP; p_idx += (int)vl) {
            vl = __riscv_vsetvl_e32m1((size_t)(_PB_NP - p_idx));
            vfloat32m1_t v_sum = __riscv_vle32_v_f32m1((const float *)&sum[p_idx], vl);
            __riscv_vse32_v_f32m1((float *)&a_rq[p_idx], v_sum, vl);
          }
        } else {
          for (; p_idx < _PB_NP; p_idx += (int)vl) {
            vl = __riscv_vsetvl_e64m1((size_t)(_PB_NP - p_idx));
            vfloat64m1_t v_sum = __riscv_vle64_v_f64m1((const double *)&sum[p_idx], vl);
            __riscv_vse64_v_f64m1((double *)&a_rq[p_idx], v_sum, vl);
          }
        }
      }
    }
  }
#pragma endscop
}

