static
void kernel_durbin(int n,
                   DATA_TYPE POLYBENCH_1D(r,N,n),
                   DATA_TYPE POLYBENCH_1D(y,N,n))
{
  DATA_TYPE z[N];
  DATA_TYPE alpha;
  DATA_TYPE beta;
  DATA_TYPE sum;

  int i, k;

#pragma scop
  y[0] = -r[0];
  beta = SCALAR_VAL(1.0);
  alpha = -r[0];

  for (k = 1; k < _PB_N; k++) {
    beta = (SCALAR_VAL(1.0) - alpha * alpha) * beta;
    sum = SCALAR_VAL(0.0);

    {
#if defined(DATA_TYPE_IS_DOUBLE)
      int base = 0;
      while (base < k) {
