static
void kernel_gemm(int ni, int nj, int nk,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		 DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		 DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_NI; i++) {
    DATA_TYPE *restrict c_row = &C[i][0];
    DATA_TYPE *restrict a_row = &A[i][0];

    j = 0;
    while (j < _PB_NJ) {
      size_t vl = __riscv_vsetvl_e64m8((size_t)(_PB_NJ - j));
      vfloat64m8_t vc = __riscv_vle64_v_f64m8(&c_row[j], vl);
      vc = __riscv_vfmul_vf_f64m8(vc, (double)beta, vl);
      __riscv_vse64_v_f64m8(&c_row[j], vc, vl);
      j += (int)vl;
    }

    for (k = 0; k < _PB_NK; k++) {
      const double scale = (double)(alpha * a_row[k]);
      DATA_TYPE *restrict b_row = &B[k][0];

      j = 0;
      while (j < _PB_NJ) {
        size_t vl = __riscv_vsetvl_e64m8((size_t)(_PB_NJ - j));
        vfloat64m8_t vc = __riscv_vle64_v_f64m8(&c_row[j], vl);
        vfloat64m8_t vb = __riscv_vle64_v_f64m8(&b_row[j], vl);
        vc = __riscv_vfmacc_vf_f64m8(vc, scale, vb, vl);
        __riscv_vse64_v_f64m8(&c_row[j], vc, vl);
        j += (int)vl;
      }
    }
  }
#pragma endscop
}

