static
void kernel_gemver(int n,
		   DATA_TYPE alpha,
		   DATA_TYPE beta,
		   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		   DATA_TYPE POLYBENCH_1D(u1,N,n),
		   DATA_TYPE POLYBENCH_1D(v1,N,n),
		   DATA_TYPE POLYBENCH_1D(u2,N,n),
		   DATA_TYPE POLYBENCH_1D(v2,N,n),
		   DATA_TYPE POLYBENCH_1D(w,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n),
		   DATA_TYPE POLYBENCH_1D(z,N,n))
{
  int i, j;

#pragma scop

#if defined(DATA_TYPE_IS_DOUBLE)

  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE u1i = u1[i];
    DATA_TYPE u2i = u2[i];
    int jj = 0;
    while (jj < _PB_N) {
      size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_N - jj));
      vfloat64m1_t a = __riscv_vle64_v_f64m1(&A[i][jj], vl);
      vfloat64m1_t vv1 = __riscv_vle64_v_f64m1(&v1[jj], vl);
      vfloat64m1_t vv2 = __riscv_vle64_v_f64m1(&v2[jj], vl);
      a = __riscv_vfmacc_vf_f64m1(a, (double)u1i, vv1, vl);
      a = __riscv_vfmacc_vf_f64m1(a, (double)u2i, vv2, vl);
      __riscv_vse64_v_f64m1(&A[i][jj], a, vl);
      jj += (int)vl;
    }
  }

  for (j = 0; j < _PB_N; j++) {
    DATA_TYPE t = beta * y[j];
    DATA_TYPE *Aj = &A[j][0];
    int ii = 0;
    while (ii < _PB_N) {
      size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_N - ii));
      vfloat64m1_t xv = __riscv_vle64_v_f64m1(&x[ii], vl);
      vfloat64m1_t av = __riscv_vle64_v_f64m1(&Aj[ii], vl);
      xv = __riscv_vfmacc_vf_f64m1(xv, (double)t, av, vl);
      __riscv_vse64_v_f64m1(&x[ii], xv, vl);
      ii += (int)vl;
    }
  }

  {
    int ii = 0;
    while (ii < _PB_N) {
      size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_N - ii));
      vfloat64m1_t xv = __riscv_vle64_v_f64m1(&x[ii], vl);
      vfloat64m1_t zv = __riscv_vle64_v_f64m1(&z[ii], vl);
      xv = __riscv_vfadd_vv_f64m1(xv, zv, vl);
      __riscv_vse64_v_f64m1(&x[ii], xv, vl);
      ii += (int)vl;
    }
  }

  for (i = 0; i < _PB_N; i++) {
    double sum = (double)w[i];
    int jj = 0;
    while (jj < _PB_N) {
      size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_N - jj));
      vfloat64m1_t av = __riscv_vle64_v_f64m1(&A[i][jj], vl);
      vfloat64m1_t xv = __riscv_vle64_v_f64m1(&x[jj], vl);
      vfloat64m1_t prod = __riscv_vfmul_vv_f64m1(av, xv, vl);
      prod = __riscv_vfmul_vf_f64m1(prod, (double)alpha, vl);
      vfloat64m1_t zero = __riscv_vfmv_v_f_f64m1(0.0, vl);
      vfloat64m1_t red = __riscv_vfredusum_vs_f64m1_f64m1(prod, zero, vl);
      sum += __riscv_vfmv_f_s_f64m1_f64(red);
      jj += (int)vl;
    }
    w[i] = (DATA_TYPE)sum;
  }

#elif defined(DATA_TYPE_IS_FLOAT)

  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE u1i = u1[i];
    DATA_TYPE u2i = u2[i];
    int jj = 0;
    while (jj < _PB_N) {
      size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_N - jj));
      vfloat32m1_t a = __riscv_vle32_v_f32m1(&A[i][jj], vl);
      vfloat32m1_t vv1 = __riscv_vle32_v_f32m1(&v1[jj], vl);
      vfloat32m1_t vv2 = __riscv_vle32_v_f32m1(&v2[jj], vl);
      a = __riscv_vfmacc_vf_f32m1(a, (float)u1i, vv1, vl);
      a = __riscv_vfmacc_vf_f32m1(a, (float)u2i, vv2, vl);
      __riscv_vse32_v_f32m1(&A[i][jj], a, vl);
      jj += (int)vl;
    }
  }

  for (j = 0; j < _PB_N; j++) {
    DATA_TYPE t = beta * y[j];
    DATA_TYPE *Aj = &A[j][0];
    int ii = 0;
    while (ii < _PB_N) {
      size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_N - ii));
      vfloat32m1_t xv = __riscv_vle32_v_f32m1(&x[ii], vl);
      vfloat32m1_t av = __riscv_vle32_v_f32m1(&Aj[ii], vl);
      xv = __riscv_vfmacc_vf_f32m1(xv, (float)t, av, vl);
      __riscv_vse32_v_f32m1(&x[ii], xv, vl);
      ii += (int)vl;
    }
  }

  {
    int ii = 0;
    while (ii < _PB_N) {
      size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_N - ii));
      vfloat32m1_t xv = __riscv_vle32_v_f32m1(&x[ii], vl);
      vfloat32m1_t zv = __riscv_vle32_v_f32m1(&z[ii], vl);
      xv = __riscv_vfadd_vv_f32m1(xv, zv, vl);
      __riscv_vse32_v_f32m1(&x[ii], xv, vl);
      ii += (int)vl;
    }
  }

  for (i = 0; i < _PB_N; i++) {
    float sum = (float)w[i];
    int jj = 0;
    while (jj < _PB_N) {
      size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_N - jj));
      vfloat32m1_t av = __riscv_vle32_v_f32m1(&A[i][jj], vl);
      vfloat32m1_t xv = __riscv_vle32_v_f32m1(&x[jj], vl);
      vfloat32m1_t prod = __riscv_vfmul_vv_f32m1(av, xv, vl);
      prod = __riscv_vfmul_vf_f32m1(prod, (float)alpha, vl);
      vfloat32m1_t zero = __riscv_vfmv_v_f_f32m1(0.0f, vl);
      vfloat32m1_t red = __riscv_vfredusum_vs_f32m1_f32m1(prod, zero, vl);
      sum += __riscv_vfmv_f_s_f32m1_f32(red);
      jj += (int)vl;
    }
    w[i] = (DATA_TYPE)sum;
  }

#else

  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_N; j++)
      A[i][j] = A[i][j] + u1[i] * v1[j] + u2[i] * v2[j];

  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_N; j++)
      x[i] = x[i] + beta * A[j][i] * y[j];

  for (i = 0; i < _PB_N; i++)
    x[i] = x[i] + z[i];

  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_N; j++)
      w[i] = w[i] +  alpha * A[i][j] * x[j];

#endif

#pragma endscop
}

