static
void kernel_gesummv(int n,
		    DATA_TYPE alpha,
		    DATA_TYPE beta,
		    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		    DATA_TYPE POLYBENCH_2D(B,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(tmp,N,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i;

#pragma scop
#if defined(DATA_TYPE_IS_DOUBLE)
  {
    const size_t max_vl = __riscv_vsetvlmax_e64m1();

    for (i = 0; i < _PB_N; i++)
      {
        DATA_TYPE *a_row = &A[i][0];
        DATA_TYPE *b_row = &B[i][0];
        size_t rem = _PB_N;
        int j = 0;
        vfloat64m1_t vacc0 = __riscv_vfmv_v_f_f64m1(0.0, max_vl);
        vfloat64m1_t vacc1 = __riscv_vfmv_v_f_f64m1(0.0, max_vl);
        vfloat64m1_t vacc2 = __riscv_vfmv_v_f_f64m1(0.0, max_vl);
        vfloat64m1_t vacc3 = __riscv_vfmv_v_f_f64m1(0.0, max_vl);

        while (rem >= (max_vl << 1))
          {
            vfloat64m1_t vx0 = __riscv_vle64_v_f64m1(&x[j], max_vl);
            vfloat64m1_t va0 = __riscv_vle64_v_f64m1(&a_row[j], max_vl);
            vfloat64m1_t vb0 = __riscv_vle64_v_f64m1(&b_row[j], max_vl);
            j += (int)max_vl;

            vfloat64m1_t vx1 = __riscv_vle64_v_f64m1(&x[j], max_vl);
            vfloat64m1_t va1 = __riscv_vle64_v_f64m1(&a_row[j], max_vl);
            vfloat64m1_t vb1 = __riscv_vle64_v_f64m1(&b_row[j], max_vl);
            j += (int)max_vl;

            vacc0 = __riscv_vfmacc_vv_f64m1(vacc0, va0, vx0, max_vl);
            vacc1 = __riscv_vfmacc_vv_f64m1(vacc1, vb0, vx0, max_vl);
            vacc2 = __riscv_vfmacc_vv_f64m1(vacc2, va1, vx1, max_vl);
            vacc3 = __riscv_vfmacc_vv_f64m1(vacc3, vb1, vx1, max_vl);

            rem -= (max_vl << 1);
          }

        while (rem >= max_vl)
          {
            vfloat64m1_t vx = __riscv_vle64_v_f64m1(&x[j], max_vl);
            vfloat64m1_t va = __riscv_vle64_v_f64m1(&a_row[j], max_vl);
            vfloat64m1_t vb = __riscv_vle64_v_f64m1(&b_row[j], max_vl);

            vacc0 = __riscv_vfmacc_vv_f64m1(vacc0, va, vx, max_vl);
            vacc1 = __riscv_vfmacc_vv_f64m1(vacc1, vb, vx, max_vl);

            j += (int)max_vl;
            rem -= max_vl;
          }

        if (rem)
          {
            size_t vl = __riscv_vsetvl_e64m1(rem);
            vfloat64m1_t vx = __riscv_vle64_v_f64m1(&x[j], vl);
