      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}

static inline DATA_TYPE
rvv_dot_product_contig(const DATA_TYPE *restrict x,
                       const DATA_TYPE *restrict y,
                       int len)
{
  int k = 0;
  DATA_TYPE sum = (DATA_TYPE)0;

#if defined(__SIZEOF_DOUBLE__) && (__SIZEOF_DOUBLE__ == __SIZEOF_POINTER__)
  if (sizeof(DATA_TYPE) == sizeof(double)) {
    vfloat64m1_t vacc = __riscv_vfmv_v_f_f64m1(0.0, 1);
    const double *xd = (const double *)x;
    const double *yd = (const double *)y;
    while (k < len) {
      size_t vl = __riscv_vsetvl_e64m1((size_t)(len - k));
      vfloat64m1_t vx = __riscv_vle64_v_f64m1(&xd[k], vl);
      vfloat64m1_t vy = __riscv_vle64_v_f64m1(&yd[k], vl);
      vacc = __riscv_vfmacc_vv_f64m1(vacc, vx, vy, vl);
      k += (int)vl;
    }
    vacc = __riscv_vfredusum_vs_f64m1_f64m1(vacc, __riscv_vfmv_v_f_f64m1(0.0, 1), 1);
    sum = (DATA_TYPE)__riscv_vfmv_f_s_f64m1_f64(vacc);
    return sum;
  }
#endif

  {
    vfloat32m1_t vacc = __riscv_vfmv_v_f_f32m1(0.0f, 1);
    const float *xf = (const float *)x;
    const float *yf = (const float *)y;
