      vacc = __riscv_vfmacc_vv_f32m1(vacc, vx, vy, vl);
      k += (int)vl;
    }
    vacc = __riscv_vfredusum_vs_f32m1_f32m1(vacc, __riscv_vfmv_v_f_f32m1(0.0f, 1), 1);
    sum = (DATA_TYPE)__riscv_vfmv_f_s_f32m1_f32(vacc);
    return sum;
  }
}

