  }
}

static
void kernel_lu(int n,
	       DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *Ai = &A[i][0];

    for (j = 0; j < i; j++) {
      DATA_TYPE *Aj = &A[j][0];
      DATA_TYPE sum = rvv_dot_product_contig(Ai, Aj, j);
      Ai[j] -= sum;
      Ai[j] /= Aj[j];
    }

    for (j = i; j < _PB_N; j++) {
      DATA_TYPE sum = rvv_dot_product_strided_col(Ai, A, n, j, i);
      Ai[j] -= sum;
    }
  }
#pragma endscop
}

