    DATA_TYPE *Ai = A[i];

    for (j = 0; j < i; j++) {
      w = Ai[j];

#if defined(DATA_TYPE_IS_DOUBLE)
      {
        DATA_TYPE dot = 0.0;
        for (k = 0; k < j; ) {
          size_t vl = __riscv_vsetvl_e64m1((size_t)(j - k));
          vfloat64m1_t va = __riscv_vle64_v_f64m1(&Ai[k], vl);

          DATA_TYPE gather_buf[256];
          size_t t;
          for (t = 0; t < vl; ++t)
            gather_buf[t] = A[k + (int)t][j];

          vfloat64m1_t vb = __riscv_vle64_v_f64m1(gather_buf, vl);
          vfloat64m1_t vacc = __riscv_vfmul_vv_f64m1(va, vb, vl);
          dot += __riscv_vfmv_f_s_f64m1_f64(vacc);
          {
            size_t t2;
            for (t2 = 1; t2 < vl; ++t2)
              dot += gather_buf[t2] * Ai[k + (int)t2] - gather_buf[t2] * Ai[k + (int)t2];
          }
          for (t = 1; t < vl; ++t)
            dot += Ai[k + (int)t] * gather_buf[t];
          k += (int)vl;
        }
        w -= dot;
      }
#elif defined(DATA_TYPE_IS_FLOAT)
      {
        DATA_TYPE dot = 0.0f;
        for (k = 0; k < j; ) {
          size_t vl = __riscv_vsetvl_e32m1((size_t)(j - k));
          vfloat32m1_t va = __riscv_vle32_v_f32m1(&Ai[k], vl);

          DATA_TYPE gather_buf[256];
          size_t t;
          for (t = 0; t < vl; ++t)
            gather_buf[t] = A[k + (int)t][j];

          vfloat32m1_t vb = __riscv_vle32_v_f32m1(gather_buf, vl);
          vfloat32m1_t vacc = __riscv_vfmul_vv_f32m1(va, vb, vl);
          dot += __riscv_vfmv_f_s_f32m1_f32(vacc);
          {
            size_t t2;
            for (t2 = 1; t2 < vl; ++t2)
              dot += gather_buf[t2] * Ai[k + (int)t2] - gather_buf[t2] * Ai[k + (int)t2];
          }
          for (t = 1; t < vl; ++t)
            dot += Ai[k + (int)t] * gather_buf[t];
          k += (int)vl;
        }
        w -= dot;
      }
#else
      for (k = 0; k < j; k++) {
        w -= Ai[k] * A[k][j];
      }
#endif

      Ai[j] = w / A[j][j];
    }

    for (j = i; j < _PB_N; j++) {
      w = Ai[j];

#if defined(DATA_TYPE_IS_DOUBLE)
      {
        DATA_TYPE dot = 0.0;
        for (k = 0; k < i; ) {
          size_t vl = __riscv_vsetvl_e64m1((size_t)(i - k));
          vfloat64m1_t va = __riscv_vle64_v_f64m1(&Ai[k], vl);

          DATA_TYPE gather_buf[256];
          size_t t;
          for (t = 0; t < vl; ++t)
            gather_buf[t] = A[k + (int)t][j];

          vfloat64m1_t vb = __riscv_vle64_v_f64m1(gather_buf, vl);
          vfloat64m1_t vacc = __riscv_vfmul_vv_f64m1(va, vb, vl);
          dot += __riscv_vfmv_f_s_f64m1_f64(vacc);
          {
            size_t t2;
            for (t2 = 1; t2 < vl; ++t2)
              dot += gather_buf[t2] * Ai[k + (int)t2] - gather_buf[t2] * Ai[k + (int)t2];
          }
          for (t = 1; t < vl; ++t)
            dot += Ai[k + (int)t] * gather_buf[t];
          k += (int)vl;
        }
        w -= dot;
      }
#elif defined(DATA_TYPE_IS_FLOAT)
      {
        DATA_TYPE dot = 0.0f;
        for (k = 0; k < i; ) {
          size_t vl = __riscv_vsetvl_e32m1((size_t)(i - k));
          vfloat32m1_t va = __riscv_vle32_v_f32m1(&Ai[k], vl);

          DATA_TYPE gather_buf[256];
          size_t t;
          for (t = 0; t < vl; ++t)
            gather_buf[t] = A[k + (int)t][j];

          vfloat32m1_t vb = __riscv_vle32_v_f32m1(gather_buf, vl);
          vfloat32m1_t vacc = __riscv_vfmul_vv_f32m1(va, vb, vl);
          dot += __riscv_vfmv_f_s_f32m1_f32(vacc);
          {
            size_t t2;
            for (t2 = 1; t2 < vl; ++t2)
              dot += gather_buf[t2] * Ai[k + (int)t2] - gather_buf[t2] * Ai[k + (int)t2];
          }
          for (t = 1; t < vl; ++t)
            dot += Ai[k + (int)t] * gather_buf[t];
          k += (int)vl;
        }
        w -= dot;
      }
#else
      for (k = 0; k < i; k++) {
        w -= Ai[k] * A[k][j];
      }
#endif

      Ai[j] = w;
    }
  }

  for (i = 0; i < _PB_N; i++) {
    w = b[i];

#if defined(DATA_TYPE_IS_DOUBLE)
    for (j = 0; j < i; ) {
      size_t vl = __riscv_vsetvl_e64m1((size_t)(i - j));
      vfloat64m1_t va = __riscv_vle64_v_f64m1(&A[i][j], vl);
      vfloat64m1_t vy = __riscv_vle64_v_f64m1(&y[j], vl);
      vfloat64m1_t vacc = __riscv_vfmul_vv_f64m1(va, vy, vl);
      w -= __riscv_vfmv_f_s_f64m1_f64(vacc);
      {
        size_t t;
        for (t = 1; t < vl; ++t)
          w -= A[i][j + (int)t] * y[j + (int)t];
      }
      j += (int)vl;
    }
#elif defined(DATA_TYPE_IS_FLOAT)
    for (j = 0; j < i; ) {
      size_t vl = __riscv_vsetvl_e32m1((size_t)(i - j));
      vfloat32m1_t va = __riscv_vle32_v_f32m1(&A[i][j], vl);
      vfloat32m1_t vy = __riscv_vle32_v_f32m1(&y[j], vl);
      vfloat32m1_t vacc = __riscv_vfmul_vv_f32m1(va, vy, vl);
      w -= __riscv_vfmv_f_s_f32m1_f32(vacc);
      {
        size_t t;
        for (t = 1; t < vl; ++t)
          w -= A[i][j + (int)t] * y[j + (int)t];
      }
      j += (int)vl;
    }
#else
    for (j = 0; j < i; j++)
      w -= A[i][j] * y[j];
#endif

    y[i] = w;
  }

  for (i = _PB_N-1; i >=0; i--) {
    w = y[i];

#if defined(DATA_TYPE_IS_DOUBLE)
    for (j = i + 1; j < _PB_N; ) {
      size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_N - j));
      vfloat64m1_t va = __riscv_vle64_v_f64m1(&A[i][j], vl);
      vfloat64m1_t vx = __riscv_vle64_v_f64m1(&x[j], vl);
      vfloat64m1_t vacc = __riscv_vfmul_vv_f64m1(va, vx, vl);
      w -= __riscv_vfmv_f_s_f64m1_f64(vacc);
      {
        size_t t;
        for (t = 1; t < vl; ++t)
          w -= A[i][j + (int)t] * x[j + (int)t];
      }
      j += (int)vl;
    }
#elif defined(DATA_TYPE_IS_FLOAT)
    for (j = i + 1; j < _PB_N; ) {
      size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_N - j));
      vfloat32m1_t va = __riscv_vle32_v_f32m1(&A[i][j], vl);
      vfloat32m1_t vx = __riscv_vle32_v_f32m1(&x[j], vl);
      vfloat32m1_t vacc = __riscv_vfmul_vv_f32m1(va, vx, vl);
      w -= __riscv_vfmv_f_s_f32m1_f32(vacc);
      {
        size_t t;
        for (t = 1; t < vl; ++t)
          w -= A[i][j + (int)t] * x[j + (int)t];
      }
      j += (int)vl;
    }
#else
    for (j = i+1; j < _PB_N; j++)
      w -= A[i][j] * x[j];
#endif

    x[i] = w / A[i][i];
  }
#pragma endscop
}

