static inline DATA_TYPE rvv_row_dot_product_f64(const DATA_TYPE* a, const DATA_TYPE* b, int n)
{
  int j = 0;
  vfloat64m1_t v_acc = __riscv_vfmv_v_f_f64m1((double)0.0, 1);

  while (j < n) {
    size_t vl = __riscv_vsetvl_e64m4((size_t)(n - j));
    vfloat64m4_t va = __riscv_vle64_v_f64m4(a + j, vl);
    vfloat64m4_t vb = __riscv_vle64_v_f64m4(b + j, vl);
    v_acc = __riscv_vfredusum_vs_f64m4_f64m1(
        __riscv_vfmul_vv_f64m4(va, vb, vl), v_acc, vl);
    j += (int)vl;
  }

  return __riscv_vfmv_f_s_f64m1_f64(v_acc);
}

static inline void rvv_x2_update_f64(int n,
				     DATA_TYPE *x2,
				     DATA_TYPE POLYBENCH_1D(y_2,N,n),
				     DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
