      vfloat64m4_t va1 = __riscv_vle64_v_f64m4(a1 + i, vl);
      vx = __riscv_vfmacc_vf_f64m4(vx, y0, va0, vl);
      vx = __riscv_vfmacc_vf_f64m4(vx, y1, va1, vl);
      __riscv_vse64_v_f64m4(x2 + i, vx, vl);
      i += (int)vl;
    }
  }

  for (; j < n; j++) {
    DATA_TYPE yv = y_2[j];
    DATA_TYPE *a = &A[j][0];
    int i = 0;
    while (i < n) {
      size_t vl = __riscv_vsetvl_e64m4((size_t)(n - i));
