    }

#if defined(DATA_TYPE_IS_DOUBLE)
  rvv_x2_update_f64(_PB_N, &x2[0], y_2, A);
#elif defined(DATA_TYPE_IS_FLOAT)
  rvv_x2_update_f32(_PB_N, &x2[0], y_2, A);
#else
  rvv_x2_update_generic(_PB_N, &x2[0], y_2, A);
#endif
#pragma endscop
}

