      if ((i * m + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}

static
void kernel_symm(int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_M; i++) {
    DATA_TYPE *Ai = &A[i][0];
    DATA_TYPE Aii = A[i][i];

    for (j = 0; j < _PB_N; j++) {
      DATA_TYPE Bij = B[i][j];
      DATA_TYPE alpha_Bij = alpha * Bij;
      DATA_TYPE temp2 = (DATA_TYPE)0;
      k = 0;

      if (sizeof(DATA_TYPE) == sizeof(double)) {
        while (k < i) {
          size_t vl = __riscv_vsetvl_e64m1((size_t)(i - k));
          vfloat64m1_t vA = __riscv_vle64_v_f64m1((const double *)&Ai[k], vl);
          vfloat64m1_t vB = __riscv_vlse64_v_f64m1((const double *)&B[k][j], (ptrdiff_t)(n * sizeof(DATA_TYPE)), vl);
          vfloat64m1_t vC = __riscv_vlse64_v_f64m1((const double *)&C[k][j], (ptrdiff_t)(n * sizeof(DATA_TYPE)), vl);

          vC = __riscv_vfmacc_vf_f64m1(vC, (double)alpha_Bij, vA, vl);
          __riscv_vsse64_v_f64m1((double *)&C[k][j], (ptrdiff_t)(n * sizeof(DATA_TYPE)), vC, vl);

          {
            vfloat64m1_t vProd = __riscv_vfmul_vv_f64m1(vB, vA, vl);
            vfloat64m1_t vZero = __riscv_vfmv_v_f_f64m1(0.0, 1);
            vfloat64m1_t vRed = __riscv_vfredusum_vs_f64m1_f64m1(vProd, vZero, vl);
            temp2 += (DATA_TYPE)__riscv_vfmv_f_s_f64m1_f64(vRed);
          }

          k += (int)vl;
        }
      } else {
        while (k < i) {
          size_t vl = __riscv_vsetvl_e32m1((size_t)(i - k));
          vfloat32m1_t vA = __riscv_vle32_v_f32m1((const float *)&Ai[k], vl);
          vfloat32m1_t vB = __riscv_vlse32_v_f32m1((const float *)&B[k][j], (ptrdiff_t)(n * sizeof(DATA_TYPE)), vl);
          vfloat32m1_t vC = __riscv_vlse32_v_f32m1((const float *)&C[k][j], (ptrdiff_t)(n * sizeof(DATA_TYPE)), vl);

          vC = __riscv_vfmacc_vf_f32m1(vC, (float)alpha_Bij, vA, vl);
          __riscv_vsse32_v_f32m1((float *)&C[k][j], (ptrdiff_t)(n * sizeof(DATA_TYPE)), vC, vl);

          {
            vfloat32m1_t vProd = __riscv_vfmul_vv_f32m1(vB, vA, vl);
            vfloat32m1_t vZero = __riscv_vfmv_v_f_f32m1(0.0f, 1);
            vfloat32m1_t vRed = __riscv_vfredusum_vs_f32m1_f32m1(vProd, vZero, vl);
            temp2 += (DATA_TYPE)__riscv_vfmv_f_s_f32m1_f32(vRed);
          }

          k += (int)vl;
        }
      }

      C[i][j] = beta * C[i][j] + alpha_Bij * Aii + alpha * temp2;
    }
  }
#pragma endscop
}

#include <stdio.h>
#include <unistd.h>
#include <string.h>
