static
void kernel_syr2k(int n, int m,
		  DATA_TYPE alpha,
		  DATA_TYPE beta,
		  DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		  DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		  DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    int limit = i + 1;

    j = 0;
    while (j < limit) {
      size_t vl = __riscv_vsetvl_e64m1((size_t)(limit - j));
      vfloat64m1_t vc = __riscv_vle64_v_f64m1(&C[i][j], vl);
      vc = __riscv_vfmul_vf_f64m1(vc, beta, vl);
      __riscv_vse64_v_f64m1(&C[i][j], vc, vl);
      j += (int)vl;
    }

    for (k = 0; k < _PB_M; k++) {
      DATA_TYPE aik_alpha = alpha * A[i][k];
      DATA_TYPE bik_alpha = alpha * B[i][k];

      j = 0;
      while (j < limit) {
        size_t vl = __riscv_vsetvl_e64m1((size_t)(limit - j));
        vfloat64m1_t vc  = __riscv_vle64_v_f64m1(&C[i][j], vl);
        vfloat64m1_t vaj = __riscv_vle64_v_f64m1(&A[j][k], vl);
        vfloat64m1_t vbj = __riscv_vle64_v_f64m1(&B[j][k], vl);

        vc = __riscv_vfmacc_vf_f64m1(vc, bik_alpha, vaj, vl);
        vc = __riscv_vfmacc_vf_f64m1(vc, aik_alpha, vbj, vl);

        __riscv_vse64_v_f64m1(&C[i][j], vc, vl);
        j += (int)vl;
      }
    }
  }
#pragma endscop
}

#include <stdio.h>
#include <unistd.h>
