static
void kernel_syrk(int n, int m,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m))
{
  int i, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *restrict Ci = &C[i][0];
    const DATA_TYPE *restrict Ai = &A[i][0];
    const int len = i + 1;
    const ptrdiff_t stride = (ptrdiff_t)m * (ptrdiff_t)sizeof(DATA_TYPE);
    int jj;

    jj = 0;
    while (jj < len) {
      size_t vl = __riscv_vsetvl_e64m8((size_t)(len - jj));
      vfloat64m8_t vc = __riscv_vle64_v_f64m8(&Ci[jj], vl);
      vc = __riscv_vfmul_vf_f64m8(vc, (double)beta, vl);
      __riscv_vse64_v_f64m8(&Ci[jj], vc, vl);
      jj += (int)vl;
    }

    for (k = 0; k + 1 < _PB_M; k += 2) {
      const DATA_TYPE scale0 = alpha * Ai[k];
      const DATA_TYPE scale1 = alpha * Ai[k + 1];
      const DATA_TYPE *restrict Ak0 = &A[0][k];
      const DATA_TYPE *restrict Ak1 = &A[0][k + 1];

      jj = 0;
      while (jj < len) {
        size_t vl = __riscv_vsetvl_e64m4((size_t)(len - jj));
        vfloat64m4_t vc = __riscv_vle64_v_f64m4(&Ci[jj], vl);
        vfloat64m4_t va0 = __riscv_vlse64_v_f64m4(&Ak0[jj], stride, vl);
        vfloat64m4_t va1 = __riscv_vlse64_v_f64m4(&Ak1[jj], stride, vl);
        vc = __riscv_vfmacc_vf_f64m4(vc, (double)scale0, va0, vl);
        vc = __riscv_vfmacc_vf_f64m4(vc, (double)scale1, va1, vl);
        __riscv_vse64_v_f64m4(&Ci[jj], vc, vl);
        jj += (int)vl;
      }
    }

    for (; k < _PB_M; k++) {
      const DATA_TYPE scale = alpha * Ai[k];
      const DATA_TYPE *restrict Ak = &A[0][k];

      jj = 0;
      while (jj < len) {
        size_t vl = __riscv_vsetvl_e64m8((size_t)(len - jj));
        vfloat64m8_t vc = __riscv_vle64_v_f64m8(&Ci[jj], vl);
        vfloat64m8_t va = __riscv_vlse64_v_f64m8(&Ak[jj], stride, vl);
        vc = __riscv_vfmacc_vf_f64m8(vc, (double)scale, va, vl);
        __riscv_vse64_v_f64m8(&Ci[jj], vc, vl);
        jj += (int)vl;
      }
    }
  }
#pragma endscop
}

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>
#include <riscv_vector.h>

#include <polybench.h>

#include "trmm.h"

static
void init_array(int m, int n,
		DATA_TYPE *alpha,
		DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j;

  *alpha = 1.5;
  for (i = 0; i < m; i++) {
    for (j = 0; j < i; j++) {
      A[i][j] = (DATA_TYPE)((i+j) % m)/m;
    }
    A[i][i] = 1.0;
    for (j = 0; j < n; j++) {
      B[i][j] = (DATA_TYPE)((n+(i-j)) % n)/n;
    }
  }
}

static
void print_array(int m, int n,
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("B");
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
      if ((i * m + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, B[i][j]);
    }
  POLYBENCH_DUMP_END("B");
  POLYBENCH_DUMP_FINISH;
}

static
void kernel_trmm(int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_M; i++) {
    DATA_TYPE *Bi = &B[i][0];

#if defined(DATA_TYPE_IS_DOUBLE)
    for (j = 0; j < _PB_N; ) {
      size_t rem = (size_t)(_PB_N - j);
      size_t vl = __riscv_vsetvl_e64m1(rem);
      vfloat64m1_t acc = __riscv_vle64_v_f64m1(&Bi[j], vl);

      for (k = i + 1; k < _PB_M; k++) {
        DATA_TYPE aik = A[k][i];
        vfloat64m1_t bk = __riscv_vle64_v_f64m1(&B[k][j], vl);
        acc = __riscv_vfmacc_vf_f64m1(acc, aik, bk, vl);
      }

      acc = __riscv_vfmul_vf_f64m1(acc, alpha, vl);
      __riscv_vse64_v_f64m1(&Bi[j], acc, vl);
      j += (int)vl;
    }

#elif defined(DATA_TYPE_IS_FLOAT)
    for (j = 0; j < _PB_N; ) {
      size_t rem = (size_t)(_PB_N - j);
      size_t vl = __riscv_vsetvl_e32m1(rem);
      vfloat32m1_t acc = __riscv_vle32_v_f32m1(&Bi[j], vl);

      for (k = i + 1; k < _PB_M; k++) {
        DATA_TYPE aik = A[k][i];
        vfloat32m1_t bk = __riscv_vle32_v_f32m1(&B[k][j], vl);
        acc = __riscv_vfmacc_vf_f32m1(acc, aik, bk, vl);
      }

      acc = __riscv_vfmul_vf_f32m1(acc, alpha, vl);
      __riscv_vse32_v_f32m1(&Bi[j], acc, vl);
      j += (int)vl;
    }

#else
    for (j = 0; j < _PB_N; j++) {
      for (k = i + 1; k < _PB_M; k++)
        B[i][j] += A[k][i] * B[k][j];
      B[i][j] = alpha * B[i][j];
    }
#endif
  }
#pragma endscop
}
